use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [test] fn push_pop () { let mut forest = ObligationForest :: new () ; forest . register_obligation ("A") ; forest . register_obligation ("B") ; forest . register_obligation ("C") ; let TestOutcome { completed : ok , errors : err , .. } = forest . process_obligations (& mut C (| obligation | match * obligation { "A" => ProcessResult :: Changed (thin_vec ! ["A.1" , "A.2" , "A.3"]) , "B" => ProcessResult :: Error ("B is for broken") , "C" => ProcessResult :: Changed (thin_vec ! []) , "A.1" | "A.2" | "A.3" => ProcessResult :: Unchanged , _ => unreachable ! () , } , | _ | { } ,)) ; assert_eq ! (ok , vec ! ["C"]) ; assert_eq ! (err , vec ! [Error { error : "B is for broken" , backtrace : vec ! ["B"] }]) ; forest . register_obligation ("D") ; let TestOutcome { completed : ok , errors : err , .. } = forest . process_obligations (& mut C (| obligation | match * obligation { "A.1" => ProcessResult :: Unchanged , "A.2" => ProcessResult :: Unchanged , "A.3" => ProcessResult :: Changed (thin_vec ! ["A.3.i"]) , "D" => ProcessResult :: Changed (thin_vec ! ["D.1" , "D.2"]) , "A.3.i" | "D.1" | "D.2" => ProcessResult :: Unchanged , _ => unreachable ! () , } , | _ | { } ,)) ; assert_eq ! (ok , Vec ::<&'static str >:: new ()) ; assert_eq ! (err , Vec :: new ()) ; let TestOutcome { completed : ok , errors : err , .. } = forest . process_obligations (& mut C (| obligation | match * obligation { "A.1" => ProcessResult :: Changed (thin_vec ! []) , "A.2" => ProcessResult :: Error ("A is for apple") , "A.3.i" => ProcessResult :: Changed (thin_vec ! []) , "D.1" => ProcessResult :: Changed (thin_vec ! ["D.1.i"]) , "D.2" => ProcessResult :: Changed (thin_vec ! ["D.2.i"]) , "D.1.i" | "D.2.i" => ProcessResult :: Unchanged , _ => unreachable ! () , } , | _ | { } ,)) ; let mut ok = ok ; ok . sort () ; assert_eq ! (ok , vec ! ["A.1" , "A.3" , "A.3.i"]) ; assert_eq ! (err , vec ! [Error { error : "A is for apple" , backtrace : vec ! ["A.2" , "A"] }]) ; let TestOutcome { completed : ok , errors : err , .. } = forest . process_obligations (& mut C (| obligation | match * obligation { "D.1.i" => ProcessResult :: Error ("D is for dumb") , "D.2.i" => ProcessResult :: Changed (thin_vec ! []) , _ => panic ! ("unexpected obligation {:?}" , obligation) , } , | _ | { } ,)) ; let mut ok = ok ; ok . sort () ; assert_eq ! (ok , vec ! ["D.2" , "D.2.i"]) ; assert_eq ! (err , vec ! [Error { error : "D is for dumb" , backtrace : vec ! ["D.1.i" , "D.1" , "D"] }]) ; }